  const [cardFollow,setCardFollow]=useState({isFollowing:false,notifyNewIntent:true,notifyNewExperience:true,notifyNewEvent:true,followerCount:0});const [followReady,setFollowReady]=useState(false);const [followSaving,setFollowSaving]=useState(false);
  const load=useCallback(async()=>{setLoading(true);setError("");try{const response=await fetch(`/api/ideas/${encodeURIComponent(selected.canonicalTargetId)}`,{cache:"no-store"});const body=await response.json() as Detail&{error?:string};if(!response.ok)throw new Error(body.error||"Kart yüklenemedi.");setDetail(body)}catch(problem){setError(problem instanceof Error?problem.message:"Kart yüklenemedi.")}finally{setLoading(false)}},[selected.canonicalTargetId]);
  useEffect(()=>{void load()},[load]);
